import type { AspectRatio } from "../types";

export interface DialogDims {
  /** CSS `aspect-ratio` value, e.g. `"9 / 16"`. */
  aspectRatio: string;
  /** Drives which dimension is the viewport-relative driver. */
  orientation: "portrait" | "landscape";
}

/**
 * Aspect → desktop dialog sizing hints per description §6.
 *
 * Mobile (< md breakpoint) always falls back to fullscreen; these hints only
 * take effect at the `md:` breakpoint, where the dialog is constructed as a
 * viewport-relative box constrained by `aspect-ratio` — height-driven for
 * portrait aspects, width-driven for landscape. The CSS in media-editor.tsx
 * sets the driver dimension to a viewport-relative size (e.g. `85dvh`) and
 * lets `aspect-ratio` compute the other.
 *
 * v0.1 does NOT expose a width-override prop — consumers needing custom sizing
 * pass `presentation="inline"` and own the wrapper.
 */
const DIALOG_DIMS_FOR_ASPECT: Record<AspectRatio, DialogDims> = {
  "9:16": { aspectRatio: "9 / 16", orientation: "portrait" },
  "1:1": { aspectRatio: "1 / 1", orientation: "portrait" },
  "16:9": { aspectRatio: "16 / 9", orientation: "landscape" },
  "4:5": { aspectRatio: "4 / 5", orientation: "portrait" },
  free: { aspectRatio: "4 / 3", orientation: "landscape" },
};

export function dialogDimsForAspect(aspect: AspectRatio): DialogDims {
  return DIALOG_DIMS_FOR_ASPECT[aspect];
}

import type Konva from "konva";
import type { CropRect } from "../types";
import { MAX_OUTPUT_PIXELS } from "./export-geometry";
import {
  BASE_IMAGE_NODE_NAME,
  TRANSFORMER_NODE_NAME,
  UI_LAYER_NAME,
} from "./placement";

/**
 * Resolve any CSS colour (`var(--x)`, `oklch(...)`, named, ...) to a concrete
 * canvas fill via computed style. Returns null (and warns once per call, dev
 * only) when the value is invalid or resolves to nothing - the export then has
 * no fill, never a silent opaque black.
 */
function resolveFillColor(value: string, host: Element | null): string | null {
  if (typeof document === "undefined" || !document.body) return value;
  const el = document.createElement("span");
  el.style.position = "absolute";
  el.style.visibility = "hidden";
  el.style.pointerEvents = "none";
  el.style.backgroundColor = value;
  const warn = () => {
    if (process.env.NODE_ENV !== "production") {
      console.warn(
        `media-editor: ignoring unresolvable export backgroundColor ${JSON.stringify(value)}`,
      );
    }
  };
  // A browser drops an invalid colour on assignment.
  if (el.style.backgroundColor === "") {
    warn();
    return null;
  }
  (host ?? document.body).appendChild(el);
  try {
    const computed = window.getComputedStyle(el).backgroundColor.trim();
    if (computed === "") {
      warn();
      return null;
    }
    // Both `rgba(0, 0, 0, 0)` and the space syntax `rgb(0 0 0 / 0)`.
    if (/^(transparent|rgba?\(\s*0[\s,]+0[\s,]+0\s*[,/]\s*0%?\s*\))$/i.test(computed)) {
      // Legitimately transparent, or a `var()` that resolved to nothing.
      if (/var\(/i.test(value)) warn();
      return null;
    }
    return computed;
  } finally {
    el.remove();
  }
}

/**
 * Prepare the stage for an export render and return the undo. Hides the
 * selection UI (Transformer handles must not be baked in) and, for a cached
 * base image, re-caches it at the export pixel ratio: Konva's cache is a
 * bitmap taken at the screen ratio, and drawing it at a higher ratio would
 * up-scale it. The ratio is capped so the cache canvas stays within the output
 * pixel limit. Tolerates partial stages (stubs).
 */
function prepareExportScene(stage: Konva.Stage, pixelRatio: number): () => void {
  const undo: Array<() => void> = [];
  const hidden = new Set<Konva.Node>();
  for (const sel of [`.${UI_LAYER_NAME}`, `.${TRANSFORMER_NODE_NAME}`]) {
    const found = typeof stage.find === "function" ? stage.find(sel) : [];
    for (const node of Array.from(found as ArrayLike<Konva.Node>)) hidden.add(node);
  }
  for (const node of hidden) {
    const was = node.visible();
    node.visible(false);
    undo.push(() => node.visible(was));
  }

  const image =
    typeof stage.findOne === "function"
      ? stage.findOne<Konva.Image>(`.${BASE_IMAGE_NODE_NAME}`)
      : undefined;
  if (image && typeof image.isCached === "function" && image.isCached()) {
    const area = Math.max(1, Math.ceil(image.width()) * Math.ceil(image.height()));
    const ratio = Math.min(pixelRatio, Math.sqrt(MAX_OUTPUT_PIXELS / area));
    image.clearCache();
    image.cache({ pixelRatio: ratio });
    undo.push(() => {
      image.clearCache();
      image.cache();
    });
  }
  return () => {
    for (const fn of undo.reverse()) fn();
  };
}

/** Run `render` (sync) against the export-prepared stage; always restores. */
function withExportScene<T>(
  stage: Konva.Stage,
  pixelRatio: number,
  render: () => T,
): T {
  const restore = prepareExportScene(stage, pixelRatio);
  try {
    return render();
  } finally {
    restore();
  }
}

export interface ExportPhotoOptions {
  stage: Konva.Stage;
  cropRect?: CropRect | null;
  /** Pixel ratio multiplier. Default 2 for retina sharpness. */
  pixelRatio?: number;
  /** Default "image/jpeg" per Q-P3 lock. PNG and WebP also supported. */
  mimeType?: "image/jpeg" | "image/png" | "image/webp";
  /** 0..1; default 0.9 per Q-P3. Only meaningful for jpeg / webp. */
  quality?: number;
  /** Fires (0) at start and (1) at end. Two-tick contract for image export. */
  onProgress?: (progress: number) => void;
  /** Fill painted under the stage content before encoding (any CSS colour). Default none. */
  backgroundColor?: string;
}

// SLICE A — stub signature fixed by the architect (U2, 0.6.0).
export interface RenderPhotoOptions {
  stage: Konva.Stage;
  /** Stage region to render, CSS px. */
  rect: CropRect;
  /** Output px per CSS px (from computeExportGeometry). */
  pixelRatio: number;
  /** Exact output size (from computeExportGeometry); the render is scaled to it. */
  width: number;
  height: number;
  mimeType?: "image/jpeg" | "image/png" | "image/webp";
  quality?: number;
  backgroundColor?: string;
  onProgress?: (progress: number) => void;
}

/**
 * Konva sizes its canvas with `floor(size * pixelRatio)`, the geometry rounds.
 * A product like 2999.9999999999995 (float error in `natural / mediaWidth`)
 * therefore comes out one pixel short and the whole image gets resampled by
 * target / (target - 1). Nudge the ratio up by a few ulps when a product sits
 * just under the integer it rounds to.
 */
export function snapPixelRatio(
  rect: { width: number; height: number },
  pixelRatio: number,
): number {
  let ratio = pixelRatio;
  for (const size of [rect.width, rect.height]) {
    const target = Math.round(size * ratio);
    if (target < 1 || Math.abs(size * ratio - target) > 1e-6) continue;
    for (let i = 0; i < 16 && Math.floor(size * ratio) < target; i++) {
      ratio *= 1 + 1e-13;
    }
  }
  return ratio;
}

/**
 * Render a stage region to a blob of exactly `width` x `height` pixels, with
 * an optional background fill, under the same two-tick progress contract.
 */
export function renderPhoto(
  opts: RenderPhotoOptions,
): Promise<{ blob: Blob; width: number; height: number }> {
  const {
    stage,
    rect,
    pixelRatio,
    width,
    height,
    mimeType = "image/jpeg",
    quality = 0.9,
    backgroundColor,
    onProgress,
  } = opts;

  onProgress?.(0);

  const ratio = snapPixelRatio(rect, pixelRatio);
  const source = withExportScene(stage, ratio, () =>
    stage.toCanvas({
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: rect.height,
      pixelRatio: ratio,
    }),
  );
  const fill = backgroundColor
    ? resolveFillColor(
        backgroundColor,
        typeof stage.container === "function" ? stage.container() : null,
      )
    : null;

  const targetW = Math.max(1, Math.round(width));
  const targetH = Math.max(1, Math.round(height));
  let out: HTMLCanvasElement;
  if (source.width === targetW && source.height === targetH) {
    // Already the target size: encode the Konva canvas itself (one canvas in
    // memory). The fill goes BEHIND the existing pixels.
    out = source;
    if (fill) {
      const ctx = out.getContext("2d");
      if (!ctx) return Promise.reject(new Error("2D context unavailable"));
      ctx.globalCompositeOperation = "destination-over";
      ctx.fillStyle = fill;
      ctx.fillRect(0, 0, out.width, out.height);
    }
  } else {
    out = document.createElement("canvas");
    out.width = targetW;
    out.height = targetH;
    const ctx = out.getContext("2d");
    if (!ctx) {
      return Promise.reject(new Error("2D context unavailable"));
    }
    if (fill) {
      ctx.fillStyle = fill;
      ctx.fillRect(0, 0, out.width, out.height);
    }
    if (
      Math.abs(source.width - targetW) <= 1 &&
      Math.abs(source.height - targetH) <= 1
    ) {
      // Off by a rounding pixel: copy 1:1 (crop / pad) instead of resampling
      // the whole picture, which would smear every edge.
      const w = Math.min(source.width, targetW);
      const h = Math.min(source.height, targetH);
      ctx.drawImage(source as CanvasImageSource, 0, 0, w, h, 0, 0, w, h);
    } else {
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(
        source as CanvasImageSource,
        0,
        0,
        source.width,
        source.height,
        0,
        0,
        out.width,
        out.height,
      );
    }
  }

  return new Promise((resolve, reject) => {
    out.toBlob(
      (blob) => {
        if (blob) {
          onProgress?.(1);
          resolve({ blob, width: out.width, height: out.height });
        } else {
          reject(new Error("Canvas.toBlob returned null"));
        }
      },
      mimeType,
      quality,
    );
  });
}

/**
 * Export the Konva stage to a Blob at the crop rect (or full stage if none).
 *
 * Uses stage.toCanvas() with x/y/width/height to write only the crop region.
 * stage.toBlob() is not available in all Konva versions; the canvas →
 * toBlob() path is more portable.
 *
 * Progress emits twice for jpeg/png/webp (start=0, end=1) per the
 * ExportImageOpts.onProgress contract. WebP encoders in some browsers may
 * yield mid-encode but we don't expose those intermediate ticks.
 */
export function exportPhotoBlob(opts: ExportPhotoOptions): Promise<Blob> {
  const {
    stage,
    cropRect,
    pixelRatio = 2,
    mimeType = "image/jpeg",
    quality = 0.9,
    onProgress,
    backgroundColor,
  } = opts;

  const region = cropRect ?? {
    x: 0,
    y: 0,
    width: stage.width(),
    height: stage.height(),
  };

  if (backgroundColor) {
    return renderPhoto({
      stage,
      rect: region,
      pixelRatio,
      width: Math.max(1, Math.round(region.width * pixelRatio)),
      height: Math.max(1, Math.round(region.height * pixelRatio)),
      mimeType,
      quality,
      backgroundColor,
      onProgress,
    }).then((r) => r.blob);
  }

  onProgress?.(0);

  const canvas = withExportScene(stage, pixelRatio, () =>
    stage.toCanvas({
      x: region.x,
      y: region.y,
      width: region.width,
      height: region.height,
      pixelRatio,
    }),
  );

  return new Promise<Blob>((resolve, reject) => {
    canvas.toBlob(
      (b) => {
        if (b) {
          onProgress?.(1);
          resolve(b);
        } else {
          reject(new Error("Canvas.toBlob returned null"));
        }
      },
      mimeType,
      quality,
    );
  });
}

/** Copy every computed style property from `src` onto `dst` inline. The
 * serialized SVG has no stylesheet, so class-driven styles (Tailwind) would
 * otherwise be lost in the rasterized output. The text-only surface is tiny
 * (a handful of nodes), so the full property walk is cheap. */
function inlineComputedStyles(src: Element, dst: HTMLElement): void {
  const cs = window.getComputedStyle(src);
  for (let i = 0; i < cs.length; i++) {
    const prop = cs.item(i);
    dst.style.setProperty(prop, cs.getPropertyValue(prop));
  }
}

/** Clone `source` for serialization: inline computed styles on every element
 * and swap textareas for divs carrying their live `.value` (a controlled
 * textarea's value lives on the DOM property, which XMLSerializer drops). */
function prepareExportClone(
  source: HTMLElement,
  width: number,
  height: number,
): HTMLElement {
  const clone = source.cloneNode(true) as HTMLElement;
  const srcNodes: Element[] = [source, ...source.querySelectorAll("*")];
  const dstNodes: Element[] = [clone, ...clone.querySelectorAll("*")];
  for (let i = 0; i < srcNodes.length; i++) {
    const src = srcNodes[i];
    const dst = dstNodes[i] as HTMLElement;
    if (src instanceof HTMLTextAreaElement) {
      const div = clone.ownerDocument.createElement("div");
      div.textContent = src.value;
      inlineComputedStyles(src, div);
      div.style.whiteSpace = "pre-wrap";
      div.style.overflow = "hidden";
      dst.replaceWith(div);
    } else {
      inlineComputedStyles(src, dst);
    }
  }
  // Pin the root to the export dimensions (the live element is positioned by
  // its parent, which isn't serialized).
  clone.style.position = "static";
  clone.style.width = `${width}px`;
  clone.style.height = `${height}px`;
  return clone;
}

/**
 * Export a text-only mode capture from the styled DOM surface.
 *
 * SVG-foreignObject technique: clone the element (computed styles inlined,
 * textarea values materialized), serialise it into an SVG, then draw the SVG
 * onto a 2× canvas. Avoids a third-party html-to-canvas dependency.
 *
 * @deprecated Use the Canvas 2D path (`exportTextCardBlob` in
 * `./text-card-export`): it honours format / quality / pixel ratio and does not
 * depend on SVG `foreignObject`. This function keeps working unchanged.
 */
export async function exportTextOnlyBlob(
  source: HTMLElement,
  width: number,
  height: number,
): Promise<Blob> {
  const xml = new XMLSerializer().serializeToString(
    prepareExportClone(source, width, height),
  );
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><foreignObject width="100%" height="100%">${xml}</foreignObject></svg>`;
  const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  try {
    const img = new Image();
    await new Promise<void>((resolve, reject) => {
      img.onload = () => resolve();
      img.onerror = () => reject(new Error("Text-mode SVG render failed"));
      img.src = url;
    });
    const canvas = document.createElement("canvas");
    canvas.width = width * 2;
    canvas.height = height * 2;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("2D context unavailable");
    ctx.scale(2, 2);
    ctx.drawImage(img, 0, 0, width, height);
    return await new Promise<Blob>((resolve, reject) => {
      canvas.toBlob(
        (b) => (b ? resolve(b) : reject(new Error("toBlob null"))),
        "image/png",
      );
    });
  } finally {
    URL.revokeObjectURL(url);
  }
}

// initial-source-loader — InitialSource intake + validation (C9).
//
// Pure helpers (no React). Resolves `InitialSource` → either a loaded
// payload (object URL + derived mode + blob) or a `SourceError` per
// description §5 validation rules:
//
//   - For `kind: "file"`, mode is derived from `File.type` prefix.
//   - For `kind: "url"`, `fetch()` is attempted; CORS / network failures
//     surface as `kind: "cors"` or `kind: "fetch-failed"`.
//   - For `kind: "blob"`, mode is the consumer-supplied value.
//   - In all paths, the resolved mode MUST be a member of `enabledModes`.
//     Mismatch → `kind: "mode-not-enabled"`.
//   - Empty / blank blobs → `kind: "invalid-blob"`.
//
// The orchestrator owns objectURL lifetime — the loader returns the URL
// and the caller is expected to revoke it on unmount / source change.

import type { ComposerMode, InitialSource, SourceError } from "../types";

export type LoadedInitialSource = {
  mode: "photo" | "video";
  blob: Blob;
  objectUrl: string;
};

export type LoadInitialSourceResult =
  | { ok: true; loaded: LoadedInitialSource }
  | { ok: false; error: SourceError };

/**
 * Derive mode from a `File.type` MIME prefix. Returns `null` for anything
 * other than `image/*` or `video/*` (consumer should treat as unsupported).
 */
export function inferModeFromFile(
  file: File,
): "photo" | "video" | null {
  const type = file.type ?? "";
  if (type.startsWith("image/")) return "photo";
  if (type.startsWith("video/")) return "video";
  return null;
}

/**
 * Resolve `InitialSource` to either a loaded payload or a `SourceError`.
 *
 * The returned object URL is allocated via `URL.createObjectURL` — caller
 * MUST revoke it (typically on unmount / next source change) to avoid
 * leaking blob references.
 *
 * `enabledModes` gates the resolved mode. If the consumer disabled the
 * mode required by the source, returns `mode-not-enabled` without
 * fetching (URL path) — so we don't waste a request on a source we
 * can't display anyway.
 */
export async function loadInitialSource(
  source: InitialSource,
  enabledModes: readonly ComposerMode[],
): Promise<LoadInitialSourceResult> {
  // Step 1 — resolve { mode, blob }. file/blob paths are sync; url path fetches.
  let mode: "photo" | "video";
  let blob: Blob;

  if (source.kind === "file") {
    const inferred = inferModeFromFile(source.file);
    if (inferred === null) {
      return {
        ok: false,
        error: {
          kind: "unsupported-file-type",
          fileType: source.file.type ?? "",
          file: source.file,
        },
      };
    }
    mode = inferred;
    blob = source.file;
  } else if (source.kind === "blob") {
    mode = source.mode;
    blob = source.blob;
  } else {
    // kind === "url"
    mode = source.mode;
    // Pre-check enabledModes before paying the network cost.
    // Empty enabledModes signals the edit-only path (initialSource without
    // capture); the mode gate only applies when the consumer has explicitly
    // enabled at least one capture mode.
    if (enabledModes.length > 0 && !enabledModes.includes(mode)) {
      return {
        ok: false,
        error: {
          kind: "mode-not-enabled",
          attempted: mode,
          enabled: [...enabledModes],
        },
      };
    }
    try {
      const res = await fetch(source.url, { mode: "cors" });
      if (!res.ok) {
        return {
          ok: false,
          error: {
            kind: "fetch-failed",
            url: source.url,
            underlying: new Error(`HTTP ${res.status} ${res.statusText}`),
          },
        };
      }
      blob = await res.blob();
    } catch (err) {
      // CORS rejection surfaces as TypeError per spec; non-CORS network
      // failures usually do too. The distinction matters for the consumer's
      // recovery path (pre-fetch + blob vs. retry url), so we attempt to
      // disambiguate via the error name + message.
      const underlying = err instanceof Error ? err : new Error(String(err));
      const looksLikeCors =
        underlying.name === "TypeError" &&
        /cors|cross.origin|failed to fetch|networkerror/i.test(
          underlying.message,
        );
      return {
        ok: false,
        error: looksLikeCors
          ? { kind: "cors", url: source.url, underlying }
          : { kind: "fetch-failed", url: source.url, underlying },
      };
    }
  }

  // Step 2 — validate against enabledModes (file/blob paths only; url path
  // pre-checked above to avoid a wasted fetch). Empty enabledModes = edit-only
  // path, same exemption as the url pre-check.
  if (enabledModes.length > 0 && !enabledModes.includes(mode)) {
    return {
      ok: false,
      error: {
        kind: "mode-not-enabled",
        attempted: mode,
        enabled: [...enabledModes],
      },
    };
  }

  // Step 3 — sanity-check the blob isn't empty.
  if (blob.size === 0) {
    return {
      ok: false,
      error: {
        kind: "invalid-blob",
        reason: "Blob is empty (size: 0).",
      },
    };
  }

  // Step 4 — allocate the object URL. Caller owns revocation.
  const objectUrl = URL.createObjectURL(blob);
  return { ok: true, loaded: { mode, blob, objectUrl } };
}

import { DEFAULT_LABELS } from "../types";
import type { MediaEditorLabels, MediaEditorResolvedLabels } from "../types";

/**
 * Nested `MediaEditorLabels` path <-> flat `MediaEditorResolvedLabels` key
 * (1:1, every flat key appears exactly once). The compile-time assertion
 * below fails when a flat key has no nested path.
 */
const NESTED_TO_FLAT = [
  [["shell", "title"], "composerLabel"],
  [["shell", "description"], "composerDescription"],
  [["shell", "back"], "back"],
  [["shell", "apply"], "apply"],
  [["shell", "cancel"], "cancel"],
  [["shell", "backToCapture"], "backToCapture"],
  [["shell", "editTools"], "editTools"],
  [["capture", "requestingCamera"], "permissionRequesting"],
  [["capture", "cameraIdle", "title"], "permissionIdleTitle"],
  [["capture", "cameraIdle", "body"], "permissionIdleBody"],
  [["capture", "cameraIdle", "enableCta"], "permissionEnable"],
  [["capture", "cameraDenied", "title"], "permissionDeniedTitle"],
  [["capture", "cameraDenied", "body"], "permissionDeniedBody"],
  [["capture", "cameraDenied", "retryCta"], "permissionRetry"],
  [["capture", "cameraDenied", "useGalleryCta"], "permissionUsePicker"],
  [["capture", "noCameraTitle"], "permissionNoCameraTitle"],
  [["capture", "cameraErrorTitle"], "permissionErrorTitle"],
  [["capture", "galleryButton"], "galleryPicker"],
  [["capture", "switchCamera"], "switchCamera"],
  [["capture", "modes", "photo"], "modePhoto"],
  [["capture", "modes", "video"], "modeVideo"],
  [["capture", "modes", "text"], "modeText"],
  [["capture", "shutter", "photo"], "shutterPhoto"],
  [["capture", "shutter", "videoStart"], "shutterVideoStart"],
  [["capture", "shutter", "videoStop"], "shutterVideoStop"],
  [["capture", "recording"], "recordingLabel"],
  [["capture", "connectCta"], "connectCamera"],
  [["capture", "connectHint"], "connectHint"],
  [["capture", "errors", "videoUnsupported"], "videoUnsupported"],
  [["capture", "errors", "videoFailed"], "videoFailed"],
  [["capture", "errors", "videoCodecUnavailable"], "videoCodecUnavailable"],
  [["toolbar", "text"], "toolText"],
  [["toolbar", "draw"], "toolDraw"],
  [["toolbar", "stickers"], "toolStickers"],
  [["toolbar", "filters"], "toolFilters"],
  [["toolbar", "adjust"], "toolAdjust"],
  [["toolbar", "crop"], "toolCrop"],
  [["adjust", "brightness"], "adjustBrightness"],
  [["adjust", "contrast"], "adjustContrast"],
  [["adjust", "saturation"], "adjustSaturation"],
  [["adjust", "blur"], "adjustBlur"],
  [["draw", "color"], "drawColor"],
  [["draw", "brushSize"], "drawBrush"],
  [["draw", "eraser"], "drawEraser"],
  [["text", "placeholder"], "textPlaceholder"],
  [["text", "fontFamily"], "textFontFamily"],
  [["text", "fontSize"], "textFontSize"],
  [["text", "alignLeft"], "textAlignLeft"],
  [["text", "alignCenter"], "textAlignCenter"],
  [["text", "alignRight"], "textAlignRight"],
  [["text", "delete"], "textDelete"],
  [["text", "background"], "textBackground"],
  [["color", "hex"], "colorHex"],
  [["color", "swatch"], "colorSwatch"],
  [["crop", "free"], "cropAspectFree"],
  [["crop", "original"], "cropAspectOriginal"],
  [["crop", "aspectCount"], "cropAspectCount"],
  [["canvas", "label"], "canvasAriaLabel"],
  [["canvas", "resetZoom"], "resetZoom"],
  [["canvas", "resizeHandle"], "resizeHandle"],
  [["trim", "start"], "trimStart"],
  [["trim", "end"], "trimEnd"],
  [["trim", "seconds"], "trimSeconds"],
  [["discard", "title"], "discardConfirmTitle"],
  [["discard", "body"], "discardConfirmBody"],
  [["discard", "cancel"], "discardCancel"],
  [["discard", "confirm"], "discardConfirm"],
  [["intake", "prompt"], "intakePrompt"],
  [["intake", "unknownType"], "fileUnknownType"],
  [["intake", "unsupportedType"], "fileUnsupportedType"],
  [["intake", "fileTooLarge"], "fileTooLarge"],
  [["empty", "noSource"], "emptyNoSource"],
  [["empty", "noSourceHint"], "emptyNoSourceHint"],
  [["empty", "noSourceAria"], "emptyNoSourceAria"],
  [["empty", "loadFailed"], "emptyLoadFailed"],
  [["empty", "attempted"], "emptyAttempted"],
  [["empty", "enabled"], "emptyEnabled"],
  [["empty", "type"], "emptyType"],
  [["empty", "blank"], "emptyBlank"],
  [["empty", "none"], "emptyNone"],
  [["empty", "noCaptureSource"], "emptyNoCaptureSource"],
  [["empty", "aspect"], "emptyAspect"],
  [["empty", "sources"], "emptySources"],
] as const satisfies ReadonlyArray<
  readonly [readonly string[], keyof MediaEditorResolvedLabels]
>;

// Compile-time exhaustiveness: resolves to `never` (and fails to compile)
// when a `MediaEditorResolvedLabels` key has no nested path in the table.
type MissingPaths = Exclude<
  keyof MediaEditorResolvedLabels,
  (typeof NESTED_TO_FLAT)[number][1]
>;
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const ALL_KEYS_HAVE_A_PATH: [MissingPaths] extends [never] ? true : never = true;

function readPath(root: unknown, path: readonly string[]): unknown {
  let cur: unknown = root;
  for (const seg of path) {
    if (cur === null || typeof cur !== "object") return undefined;
    cur = (cur as Record<string, unknown>)[seg];
  }
  return cur;
}

type FlatKey = keyof MediaEditorResolvedLabels;

/** Runtime kind of a label key: "function" for parameterised templates, else "string". */
function kindOf(key: string): "string" | "function" | undefined {
  const entry = NESTED_TO_FLAT.find((e) => e[1] === key);
  if (!entry) return undefined;
  const v = readPath(DEFAULT_LABELS, entry[0]);
  return typeof v === "function" ? "function" : "string";
}

/**
 * Normalizes the `labels` prop onto the flat `MediaEditorResolvedLabels`
 * shape (partial: only the keys that were set).
 *
 * Accepts the nested `MediaEditorLabels` shape, the flat shape (deprecated;
 * what story-composer passed before 0.5.0), or a mix. Nested values are
 * applied first, then flat keys are spread over them, so flat wins on
 * conflict. String-valued keys must be strings and function-valued keys must
 * be functions; anything else is ignored. Unknown flat string keys pass
 * through untouched.
 */
export function normalizeEditorLabels(
  input: unknown,
): Partial<MediaEditorResolvedLabels> {
  const out: Record<string, unknown> = {};
  if (input === null || typeof input !== "object") return out;

  for (const [path, flatKey] of NESTED_TO_FLAT) {
    const v = readPath(input, path);
    if (typeof v === kindOf(flatKey)) out[flatKey] = v;
  }
  for (const [k, v] of Object.entries(input as Record<string, unknown>)) {
    const kind = kindOf(k);
    if (kind === undefined ? typeof v === "string" : typeof v === kind) {
      out[k] = v;
    }
  }
  return out as Partial<MediaEditorResolvedLabels>;
}

/**
 * The fully populated label set: `DEFAULT_LABELS` (the single source of the
 * English strings) with the consumer's labels (nested, flat or mixed) merged
 * over it.
 */
export function resolveEditorLabels(input: unknown): MediaEditorResolvedLabels {
  return {
    ...normalizeEditorLabels(DEFAULT_LABELS),
    ...normalizeEditorLabels(input),
  } as MediaEditorResolvedLabels;
}

/**
 * Inverse of the nested -> flat table: converts a flat label object (for
 * example a host's own flat labels) into the nested `MediaEditorLabels` shape
 * the `labels` prop takes. Keys it does not know are ignored, so an object
 * with extra keys is fine.
 */
export function editorLabelsFromFlat(
  flat: Partial<MediaEditorResolvedLabels>,
): MediaEditorLabels {
  const out: Record<string, unknown> = {};
  const source = flat as Record<string, unknown>;
  for (const [path, flatKey] of NESTED_TO_FLAT) {
    const v = source[flatKey as FlatKey];
    if (typeof v !== kindOf(flatKey)) continue;
    let cur = out;
    for (let i = 0; i < path.length - 1; i++) {
      const seg = path[i]!;
      const next = cur[seg];
      if (next === undefined || next === null || typeof next !== "object") {
        cur[seg] = {};
      }
      cur = cur[seg] as Record<string, unknown>;
    }
    cur[path[path.length - 1]!] = v;
  }
  return out as MediaEditorLabels;
}

import type { FilterPreset, KonvaFilterSpec } from "../types";

/**
 * Built-in filter presets (Q-P9-style Instagram-inspired chains, recreated
 * with Konva's filter primitives + reusable param overrides).
 *
 * Each preset is applied by:
 *   node.cache();
 *   node.filters(buildKonvaFilterChain(preset.konvaFilters));
 *   node.brightness(params.brightness ?? 0);
 *   // ...etc. per filter
 *
 * Real wiring lives in `composer-editor.tsx` — this file ships the data.
 */

