import { cn } from "@/lib/utils";
import type { ComposerMode, MediaEditorResolvedLabels } from "../types";

export interface ModeTogglePillProps {
  mode: ComposerMode;
  visibleModes: ComposerMode[];
  labels: MediaEditorResolvedLabels;
  onModeChange: (mode: ComposerMode) => void;
  className?: string;
}

const ORDER: ComposerMode[] = ["photo", "video", "text"];

/**
 * Plain-button segmented control. Deliberately NOT shadcn ToggleGroup — its
 * value model diverges between Radix (single: string) and Base UI (string[]),
 * an F-cross-13 carrier that breaks Base-UI consumers (filter-panel 0.1.1 /
 * event-calendar v0.2.1 precedent: same swap). Re-tapping the active mode stays
 * a noop (ToggleGroup used to emit "" on re-tap; here we simply don't fire).
 */
export function ModeTogglePill({
  mode,
  visibleModes,
  labels,
  onModeChange,
  className,
}: ModeTogglePillProps) {
  if (visibleModes.length < 2) return null;

  const orderedVisible = ORDER.filter((m) => visibleModes.includes(m));

  return (
    <div
      role="group"
      className={cn(
        "inline-flex rounded-full bg-media-overlay backdrop-blur-md p-1 text-media-overlay-foreground",
        className,
      )}
    >
      {orderedVisible.map((m) => {
        const active = m === mode;
        return (
          <button
            key={m}
            type="button"
            aria-pressed={active}
            aria-label={labelFor(m, labels)}
            onClick={() => {
              if (!active) onModeChange(m);
            }}
            className={cn(
              "rounded-full px-4 py-1.5 text-xs font-medium tracking-wide uppercase",
              "transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              active
                ? "bg-media-overlay-foreground text-black"
                : "text-media-overlay-foreground/80 hover:bg-media-overlay-foreground/10 hover:text-media-overlay-foreground",
            )}
          >
            {labelFor(m, labels)}
          </button>
        );
      })}
    </div>
  );
}

function labelFor(
  mode: ComposerMode,
  labels: MediaEditorResolvedLabels,
): string {
  switch (mode) {
    case "photo":
      return labels.modePhoto;
    case "video":
      return labels.modeVideo;
    case "text":
      return labels.modeText;
  }
}

