// ─── Geometry helpers (consumed by editor-canvas) ─────────────────────

// CropRect now lives in ../types — single source of truth across the procomp.
// Re-exported here for any v0.1.5 consumer of story-composer that imported
// `CropRect` from `parts/tool-crop-overlay` (story-composer v0.2.0 barrel
// preserves the re-export for backward-compat).
export type { CropRect };

export const ASPECT_RATIO_VALUES: Record<AspectRatio, number | null> = {
  "9:16": 9 / 16,
  "1:1": 1,
  "16:9": 16 / 9,
  "4:5": 4 / 5,
  free: null,
};

/**
 * Centered, max-fitting rect for the given aspect ratio inside the stage — or
 * inside `bounds` (for example the photo's displayed rect) when given.
 * Returns the whole stage / bounds rect for "free" (no constraint).
 */
export function fitCropToStage(
  aspect: AspectRatio,
  stageWidth: number,
  stageHeight: number,
  bounds?: CropRect,
): CropRect {
  const box: CropRect = bounds ?? {
    x: 0,
    y: 0,
    width: stageWidth,
    height: stageHeight,
  };
  const ratio = ASPECT_RATIO_VALUES[aspect];
  if (ratio === null) {
    return { ...box };
  }
  // Find largest rect with the given aspect that fits inside the box.
  let width = box.width;
  let height = box.width / ratio;
  if (height > box.height) {
    height = box.height;
    width = box.height * ratio;
  }
  return {
    x: box.x + (box.width - width) / 2,
    y: box.y + (box.height - height) / 2,
    width,
    height,
  };
}

