import type { MediaEditorResolvedLabels, ValidationError } from "../types";
import { resolveEditorLabels } from "./normalize-labels";
import { formatNumber } from "./format-number";

export interface ValidateGalleryFileOptions {
  /** Message templates (the intake keys of the resolved labels). Default: the English defaults. */
  labels?: Pick<
    MediaEditorResolvedLabels,
    "fileUnknownType" | "fileUnsupportedType" | "fileTooLarge"
  >;
  /** BCP 47 locale for the sizes in the message. Default: `"en"`. */
  locale?: string;
  /**
   * Accepted MIME types (`MediaEditorProps.acceptMediaTypes`); wildcards such
   * as `"video/*"` are allowed. Default `["image/*", "video/*"]`.
   */
  acceptMediaTypes?: readonly string[];
}

/** Default intake accept list. */
export const DEFAULT_ACCEPT_MEDIA_TYPES: readonly string[] = ["image/*", "video/*"];

/** The value for an `<input type="file" accept>` attribute. */
export function acceptAttribute(accept?: readonly string[]): string {
  return (accept && accept.length > 0 ? accept : DEFAULT_ACCEPT_MEDIA_TYPES).join(",");
}

/**
 * True when `fileType` satisfies one entry of `accept`. Entries are exact MIME
 * types (`"video/mp4"`) or `type/*` wildcards; parameters on the file type
 * (`"video/webm;codecs=vp9"`) are ignored. Matching is case-insensitive.
 */
export function matchesAccept(
  fileType: string,
  accept?: readonly string[],
): boolean {
  const list = accept && accept.length > 0 ? accept : DEFAULT_ACCEPT_MEDIA_TYPES;
  const type = (fileType.split(";")[0] ?? "").trim().toLowerCase();
  if (!type) return false;
  return list.some((entry) => {
    const e = (entry.split(";")[0] ?? "").trim().toLowerCase();
    if (!e) return false;
    if (e === "*/*") return true;
    if (e.endsWith("/*")) return type.startsWith(e.slice(0, -1));
    return type === e;
  });
}

/**
 * Gallery/file-intake validation — type + size check. Generic (not
 * camera-specific): lives in BASE so the file/gallery intake surface works
 * with the capture feature slice absent (P3 S3 — the pure-CAPTURE files
 * moved to `features/capture/`, but picking a file off disk isn't a capture
 * concern). Used by the base file-intake surface (media-editor.tsx) AND by
 * `features/capture/parts/editor-camera.tsx`'s gallery button — the feature
 * imports this DIRECTLY (relative into base), never through the barrel.
 *
 * `ValidationError.message` is built from the `intake` labels, so it is
 * translated like the rest of the editor.
 */
export function validateGalleryFile(
  file: File,
  maxFileSizeMb: number,
  options?: ValidateGalleryFileOptions,
): ValidationError | null {
  const labels = options?.labels ?? resolveEditorLabels(undefined);
  // The editor can only edit images and videos, so a custom accept list that
  // names another family (e.g. "application/pdf") still cannot get past this.
  const editable =
    file.type.startsWith("image/") || file.type.startsWith("video/");
  if (!editable || !matchesAccept(file.type, options?.acceptMediaTypes)) {
    return {
      kind: "unsupported-type",
      message: labels.fileUnsupportedType(file.type || labels.fileUnknownType),
      file,
    };
  }
  const bytes = file.size;
  const maxBytes = maxFileSizeMb * 1024 * 1024;
  if (bytes > maxBytes) {
    const sizeMb = bytes / 1024 / 1024;
    return {
      kind: "file-too-large",
      message: labels.fileTooLarge(
        sizeMb,
        maxFileSizeMb,
        formatNumber(sizeMb, options?.locale, { min: 1, grouping: false }),
        formatNumber(maxFileSizeMb, options?.locale, { max: 3, grouping: false }),
      ),
      file,
    };
  }
  return null;
}

// Local default-export wrapper so `React.lazy(() => import("./lazy-editor-canvas"))`
// has a target — `EditorCanvas` itself is a named export. Same-folder
// (intra-component): this carries none of the cross-procomp rewriter hazards
// the media-library `lazy-code-block.tsx` / `lazy-markdown-editor.tsx`
// wrappers document (no category segment to mangle, no other registry item
// involved) — it exists purely for the `React.lazy(...)` default-export
// contract. Compound-component-structure rule: the konva canvas is the
// heavy dep (konva + react-konva) every consumer pulls in, so it gets the
// mandated lazy boundary even though (unlike media-library's viewers) it
// isn't itself droppable — the win here is deferring the konva chunk off
// the editor's initial paint (capture stage / text-only mode never need it).
export { EditorCanvas as default } from "./editor-canvas";

"use client";

import { useEffect, useRef } from "react";
import { isEditableTarget } from "../lib/is-editable-target";

export interface UseGlobalKeydownOptions {
  /** Attach only while true. Default `true`. */
  enabled?: boolean;
  /** Listen in the capture phase. Default `false`. */
  capture?: boolean;
}

/**
 * The one way a registry component listens for keys on `window` (consumer contract C9 /
 * R8). The handler is skipped for events typed into an editable target (see
 * `isEditableTarget`), events another handler already `preventDefault`-ed, and IME
 * composition (`isComposing`, or the legacy keyCode 229).
 *
 * `validate-contract` fails any other `window` / `document` keydown listener in shipped
 * files unless it carries `// keydown-ok: <reason>`.
 *
 * Local copy of the canonical `_template/_snippets/use-global-keydown.ts`.
 */
export function useGlobalKeydown(
  handler: (event: KeyboardEvent) => void,
  { enabled = true, capture = false }: UseGlobalKeydownOptions = {},
): void {
  const handlerRef = useRef(handler);
  useEffect(() => {
    handlerRef.current = handler;
  });
  useEffect(() => {
    if (!enabled || typeof window === "undefined") return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.isComposing || event.keyCode === 229) return;
      // The real origin: inside an open shadow root `event.target` is retargeted to the host.
      const origin = (typeof event.composedPath === "function" && event.composedPath()[0]) || event.target;
      if (isEditableTarget(origin)) return;
      handlerRef.current(event);
    };
    window.addEventListener("keydown", onKeyDown, capture);
    return () => window.removeEventListener("keydown", onKeyDown, capture);
  }, [enabled, capture]);
}

/**
 * True when a keyboard event's target is somewhere the user is typing or that owns its
 * keys (consumer contract C9 / R8): a text-entry `<input>`, `<textarea>`, `<select>`,
 * contentEditable, `[role="textbox"]`, a widget that owns the arrow keys (`slider`,
 * `spinbutton`, `combobox`, `listbox`), or anything inside `[data-keyboard-ignore]`.
 * Window-level shortcuts must stand down for these.
 *
 * Copy into a component's `lib/` — registry items stay self-contained. Canonical copy:
 * `src/registry/components/_template/_snippets/` (tests next to it).
 */
const NON_TEXT_INPUTS = new Set(["checkbox", "radio", "button", "submit", "reset", "image", "file", "color"]);

export function isEditableTarget(target: EventTarget | null): boolean {
  if (!target || typeof (target as Element).closest !== "function") return false;
  const el = target as HTMLElement;
  if (el.tagName === "INPUT") return !NON_TEXT_INPUTS.has((el as HTMLInputElement).type);
  if (el.tagName === "TEXTAREA" || el.tagName === "SELECT") return true;
  if (el.isContentEditable) return true;
  return (
    el.closest(
      '[contenteditable=""], [contenteditable="true"], [role="textbox"], [role="slider"], [role="spinbutton"], [role="combobox"], [role="listbox"], [data-keyboard-ignore]',
    ) !== null
  );
}

/**
 * Locale-aware number text for the values the editor shows to users (trim
 * seconds, crop-aspect count, adjust values). `locale` is a BCP 47 tag;
 * default `"en"` (deterministic, so server and client render the same text).
 * `grouping: false` drops thousands separators (e.g. "1000" not "1,000"). An invalid tag falls back to `"en"` instead of throwing.
 */
export function formatNumber(
  value: number,
  locale: string | undefined,
  fractionDigits: { min?: number; max?: number; grouping?: boolean } = {},
): string {
  const options: Intl.NumberFormatOptions = {
    useGrouping: fractionDigits.grouping ?? true,
    minimumFractionDigits: fractionDigits.min ?? 0,
    maximumFractionDigits: fractionDigits.max ?? fractionDigits.min ?? 0,
  };
  try {
    return new Intl.NumberFormat(locale ?? "en", options).format(value);
  } catch {
    return new Intl.NumberFormat("en", options).format(value);
  }
}

import type {
  FilterPreset,
  FontOption,
  GradientPreset,
  MediaEditorPresetNames,
  StickerSet,
} from "../types";

/**
 * Applies `labels.presets` (id -> display name) to preset data. Presets whose
 * id has no entry keep their own label; the input is returned as-is (same
 * identity) when there is nothing to rename.
 */

export function renameBackgrounds(
  items: GradientPreset[],
  names: MediaEditorPresetNames["backgrounds"],
): GradientPreset[] {
  if (!names) return items;
  return items.map((g) => (names[g.id] ? { ...g, label: names[g.id]! } : g));
}

export function renameFonts(
  items: FontOption[],
  names: MediaEditorPresetNames["fonts"],
): FontOption[] {
  if (!names) return items;
  return items.map((f) => (names[f.id] ? { ...f, label: names[f.id]! } : f));
}

export function renameFilters(
  items: FilterPreset[],
  names: MediaEditorPresetNames["filters"],
): FilterPreset[] {
  if (!names) return items;
  return items.map((f) => (names[f.id] ? { ...f, label: names[f.id]! } : f));
}

export function renameStickerSets(
  sets: StickerSet[],
  setNames: MediaEditorPresetNames["stickerSets"],
  stickerNames: MediaEditorPresetNames["stickers"],
): StickerSet[] {
  if (!setNames && !stickerNames) return sets;
  return sets.map((set) => ({
    ...set,
    label: setNames?.[set.id] ?? set.label,
    stickers: stickerNames
      ? set.stickers.map((s) =>
          stickerNames[s.id] ? { ...s, alt: stickerNames[s.id]! } : s,
        )
      : set.stickers,
  }));
}

export interface VideoProbe {
  width: number;
  height: number;
  /** Rounded to whole milliseconds; omitted when the container reports no finite duration. */
  durationMs?: number;
}

/**
 * Reads a video blob's intrinsic size and duration through a detached
 * `<video>` element (`loadedmetadata`). Resolves `null` when the metadata does
 * not arrive within `timeoutMs`, the blob fails to decode, or the platform has
 * no DOM — callers fall back to their own defaults. Never rejects.
 */
export function probeVideo(
  blob: Blob,
  timeoutMs = 1500,
): Promise<VideoProbe | null> {
  if (typeof document === "undefined" || typeof URL === "undefined") {
    return Promise.resolve(null);
  }
  return new Promise((resolve) => {
    let url: string;
    try {
      url = URL.createObjectURL(blob);
    } catch {
      resolve(null);
      return;
    }
    const video = document.createElement("video");
    let settled = false;
    const finish = (result: VideoProbe | null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      video.removeAttribute("src");
      video.load?.();
      URL.revokeObjectURL(url);
      resolve(result);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    video.preload = "metadata";
    video.muted = true;
    video.onloadedmetadata = () => {
      const { videoWidth, videoHeight, duration } = video;
      if (!videoWidth || !videoHeight) {
        finish(null);
        return;
      }
      finish({
        width: videoWidth,
        height: videoHeight,
        durationMs: Number.isFinite(duration)
          ? Math.round(duration * 1000)
          : undefined,
      });
    };
    video.onerror = () => finish(null);
    video.src = url;
  });
}

import type { KeyboardEvent } from "react";

/** Elements a keyboard user can land on inside a consumer overlay. */
export const OVERLAY_FOCUSABLE =
  'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';

const isJsdom = () =>
  typeof navigator !== "undefined" && /jsdom/i.test(navigator.userAgent);

/** Not `[hidden]`, not `display:none` / `visibility:hidden`, and laid out. */
function isReachable(el: HTMLElement, host: HTMLElement): boolean {
  if (el.closest("[hidden]")) return false;
  for (let n: HTMLElement | null = el; n; n = n.parentElement) {
    const cs = getComputedStyle(n);
    if (cs.display === "none") return false;
    if (n === el && cs.visibility === "hidden") return false;
    if (n === host) break;
  }
  // jsdom has no layout: every element reports zero rects there.
  if (!isJsdom() && el.getClientRects().length === 0) return false;
  return true;
}

/** The overlay's focusable, reachable descendants in DOM order. */
export function overlayTabbables(host: HTMLElement): HTMLElement[] {
  return Array.from(host.querySelectorAll<HTMLElement>(OVERLAY_FOCUSABLE)).filter(
    (el) => isReachable(el, host),
  );
}

/** First reachable focusable inside the overlay, else the host itself. */
export function focusOverlay(host: HTMLElement) {
  (overlayTabbables(host)[0] ?? host).focus({ preventScroll: true });
}

/**
 * Keeps Tab / Shift+Tab inside the overlay. The rest of the editor is `inert`,
 * but a dialog's own focus scope ignores `inert` when it picks its first / last
 * candidate, so Tab from the overlay's last control would otherwise stick (or
 * leave the page) instead of wrapping.
 */
export function wrapTabWithinOverlay(e: KeyboardEvent<HTMLElement>) {
  if (e.key !== "Tab" || e.defaultPrevented) return;
  const host = e.currentTarget;
  const items = overlayTabbables(host);
  const active = document.activeElement;
  if (items.length === 0) {
    e.preventDefault();
    host.focus({ preventScroll: true });
    return;
  }
  const first = items[0]!;
  const last = items[items.length - 1]!;
  if (e.shiftKey && (active === first || active === host)) {
    e.preventDefault();
    last.focus({ preventScroll: true });
  } else if (!e.shiftKey && active === last) {
    e.preventDefault();
    first.focus({ preventScroll: true });
  }
}

import type Konva from "konva";

/** Name given to the base image node in `EditorCanvas`, so placement can find it. */
export const BASE_IMAGE_NODE_NAME = "media-editor-base-image";

/** Names of the selection UI (layer + Transformer); exports hide them. */
export const UI_LAYER_NAME = "media-editor-ui-layer";
export const TRANSFORMER_NODE_NAME = "media-editor-transformer";

export interface PlacementPoint {
  x: number;
  y: number;
}

interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * Centre of the part of the image the user can currently see, in stage
 * coordinates (the space overlay `x` / `y` live in). The visible part is the
 * image rect intersected with the viewport after pan / zoom. With no image
 * yet, or the image panned fully out of view, it is the viewport centre.
 * `null` when the stage has not mounted.
 */
export function visibleImageCenter(stage: Konva.Stage | null): PlacementPoint | null {
  const area = visibleImageArea(stage);
  return area ? { x: area.x + area.width / 2, y: area.y + area.height / 2 } : null;
}

/**
 * The part of the image the user can currently see, in stage coordinates
 * (see `visibleImageCenter`). `null` when the stage has not mounted.
 */
export function visibleImageArea(
  stage: Konva.Stage | null,
): { x: number; y: number; width: number; height: number } | null {
  if (!stage) return null;
  const scale = stage.scaleX() || 1;
  const viewport: Rect = {
    x: -stage.x() / scale,
    y: -stage.y() / scale,
    width: stage.width() / scale,
    height: stage.height() / scale,
  };
  const node = stage.findOne(`.${BASE_IMAGE_NODE_NAME}`);
  const image: Rect | null = node
    ? { x: node.x(), y: node.y(), width: node.width(), height: node.height() }
    : null;
  const visible = image ? intersect(image, viewport) : null;
  return visible ?? viewport;
}

/**
 * Top-left (and, when needed, a smaller font size) for a new text box centred
 * on `area`, so the whole box starts inside it: a box wider than 90 % of the
 * area is scaled down (never below 12 px), then the position is clamped.
 * `measure` returns the box for a font size.
 */
export function fitTextInArea(
  area: { x: number; y: number; width: number; height: number },
  fontSize: number,
  measure: (size: number) => { width: number; height: number },
): { x: number; y: number; fontSize: number } {
  let size = fontSize;
  let box = measure(size);
  const maxWidth = area.width * 0.9;
  if (box.width > maxWidth && box.width > 0) {
    size = Math.max(12, Math.floor((size * maxWidth) / box.width));
    box = measure(size);
  }
  const clamp = (v: number, min: number, span: number, len: number) =>
    len >= span ? min : Math.min(Math.max(v, min), min + span - len);
  return {
    x: clamp(area.x + area.width / 2 - box.width / 2, area.x, area.width, box.width),
    y: clamp(area.y + area.height / 2 - box.height / 2, area.y, area.height, box.height),
    fontSize: size,
  };
}

function intersect(a: Rect, b: Rect): Rect | null {
  const x = Math.max(a.x, b.x);
  const y = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const bottom = Math.min(a.y + a.height, b.y + b.height);
  if (right <= x || bottom <= y) return null;
  return { x, y, width: right - x, height: bottom - y };
}

const isJsdom = () =>
  typeof navigator !== "undefined" && /jsdom/i.test(navigator.userAgent);

let measureContext: CanvasRenderingContext2D | null | undefined;

const resolvedFamilies = new Map<string, string>();

/** `var(--x, a, b)` becomes `a, b` (the var() fallback list); else the input. */
function varFallbackList(value: string): string {
  const out = value.replace(
    /var\(\s*--[^,()]+,\s*((?:[^()]|\([^()]*\))*)\)/g,
    "$1",
  );
  return out.includes("var(") ? "sans-serif" : out;
}

/**
 * A canvas rejects a `font` string containing `var()` (Chromium falls back to
 * `10px sans-serif`), so a token-bearing family must become a concrete family
 * list before it reaches Konva or `measureText`. Resolved through computed
 * style, cached per value; SSR-safe; falls back to the `var()` fallback list.
 * The stored value (`TextOverlay.fontFamily`) stays the token.
 */
export function resolveCanvasFontFamily(family: string): string {
  if (!family.includes("var(")) return family;
  const cached = resolvedFamilies.get(family);
  if (cached !== undefined) return cached;
  let result = varFallbackList(family);
  if (typeof document !== "undefined" && document.body) {
    const el = document.createElement("span");
    el.style.position = "absolute";
    el.style.visibility = "hidden";
    el.style.pointerEvents = "none";
    el.style.fontFamily = family;
    document.body.appendChild(el);
    try {
      const computed = window.getComputedStyle(el).fontFamily;
      if (computed && !computed.includes("var(")) result = computed;
    } finally {
      el.remove();
    }
  }
  resolvedFamilies.set(family, result);
  return result;
}

/** Quote family names that contain spaces, the way Konva builds its font string. */
function cssFontFamily(family: string): string {
  return family
    .split(",")
    .map((f) => {
      const name = f.trim();
      return /\s/.test(name) && !/^["']/.test(name) ? `"${name}"` : name;
    })
    .join(", ");
}

/**
 * Size of a Konva text node with default padding / line height (1), measured
 * the way Konva measures it (canvas `measureText`). Without a 2D context
 * (jsdom, SSR) it falls back to an estimate of 0.6em per character.
 */
export function measureTextBox(
  text: string,
  fontFamily: string,
  fontSize: number,
): { width: number; height: number } {
  const lines = text.split("\n");
  if (measureContext === undefined) {
    measureContext =
      typeof document === "undefined" || isJsdom()
        ? null
        : document.createElement("canvas").getContext("2d");
  }
  let width: number;
  if (measureContext) {
    measureContext.font = `${fontSize}px ${cssFontFamily(resolveCanvasFontFamily(fontFamily))}`;
    width = Math.max(...lines.map((l) => measureContext!.measureText(l).width));
  } else {
    width = Math.max(...lines.map((l) => l.length)) * fontSize * 0.6;
  }
  return { width, height: lines.length * fontSize };
}

/** Used only if an overlay is added before the stage has mounted. */
export const FALLBACK_PLACEMENT: PlacementPoint = { x: 100, y: 200 };

import type { AspectRatio, CropAspect } from "../types";

const NAMED: Record<AspectRatio, number | null> = {
  "9:16": 9 / 16,
  "1:1": 1,
  "16:9": 16 / 9,
  "4:5": 4 / 5,
  free: null,
};

function isNamed(value: string): value is AspectRatio {
  return Object.prototype.hasOwnProperty.call(NAMED, value);
}

function parsePositive(part: string): number | null {
  if (part === "" || part !== part.trim()) return null;
  const n = Number(part);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/** Parse "W:H" (finite positive numbers) into its width / height ratio. */
function parseCustom(value: string): number | null {
  const parts = value.split(":");
  if (parts.length !== 2) return null;
  const w = parsePositive(parts[0]);
  const h = parsePositive(parts[1]);
  if (w === null || h === null) return null;
  const ratio = w / h;
  return Number.isFinite(ratio) && ratio > 0 ? ratio : null;
}

/** True for every `AspectRatio`, `"original"`, and `"W:H"` with finite positive numbers. */
export function isValidCropAspect(value: unknown): value is CropAspect {
  if (typeof value !== "string") return false;
  if (value === "original") return true;
  if (isNamed(value)) return true;
  return parseCustom(value) !== null;
}

/**
 * Width / height ratio for a crop aspect. `null` = free (no lock).
 * `"original"` uses `mediaRatio` (the loaded photo's width / height); when that
 * is unknown it is `null` (free) until the photo has loaded.
 */
export function cropAspectToRatio(
  aspect: CropAspect,
  mediaRatio: number | null,
): number | null {
  if (aspect === "original") {
    return mediaRatio !== null && Number.isFinite(mediaRatio) && mediaRatio > 0
      ? mediaRatio
      : null;
  }
  if (isNamed(aspect)) return NAMED[aspect];
  return parseCustom(aspect);
}

import type { CropRect, ExportImageOpts } from "../types";

export interface ExportGeometryInput {
  /** Stage size, CSS px. */
  stage: { width: number; height: number };
  /** The photo's displayed rect on the stage, CSS px (null: no photo). */
  media: CropRect | null;
  /** The crop frame while one is set, CSS px. */
  crop: CropRect | null;
  /** The photo's natural width in pixels (for the `region: "media"` default). */
  naturalWidth?: number;
  opts: Pick<
    ExportImageOpts,
    "region" | "pixelRatio" | "width" | "height" | "maxEdge"
  >;
}

export interface ExportGeometry {
  /** Stage region to render, CSS px. */
  rect: CropRect;
  /** Pixel ratio to render it at (output px per CSS px). */
  pixelRatio: number;
  /** Output size in pixels (integers, ≥ 1). */
  width: number;
  height: number;
}

const DEFAULT_PIXEL_RATIO = 2;

/** Longer-edge cap for the natural-resolution default (`region: "media"`). */
export const NATURAL_MAX_EDGE = 4096;
/** Total output pixels any export may have (the iOS canvas area limit). */
export const MAX_OUTPUT_PIXELS = 16_777_216;

const good = (n: number | undefined): n is number =>
  typeof n === "number" && Number.isFinite(n) && n > 0;

const toPx = (n: number) => Math.max(1, Math.round(n));

function intersect(a: CropRect, b: CropRect): CropRect {
  const x = Math.max(a.x, b.x);
  const y = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const bottom = Math.min(a.y + a.height, b.y + b.height);
  return { x, y, width: right - x, height: bottom - y };
}

/**
 * Resolve the export region and output size, following the `ExportImageOpts`
 * docs: region "stage" = crop ?? whole stage; region "media" = media ∩ crop
 * (media alone without crop). Size: width/height (both → region centre-trimmed
 * to that aspect) > maxEdge cap > pixelRatio (default 2; for region "media"
 * with no size option, naturalWidth / media.width, longer edge capped at 4096).
 * Every result is capped at 16_777_216 total pixels (uniform scale-down). Throws
 * a `RangeError` when the region is empty (no photo for "media", zero-size stage).
 */
export function computeExportGeometry(
  input: ExportGeometryInput,
): ExportGeometry {
  return capPixels(resolveGeometry(input));
}

/** Scale a result down uniformly so it stays within MAX_OUTPUT_PIXELS. */
function capPixels(g: ExportGeometry): ExportGeometry {
  if (g.width * g.height <= MAX_OUTPUT_PIXELS) return g;
  const s = Math.sqrt(MAX_OUTPUT_PIXELS / (g.width * g.height));
  // floor keeps width * height <= MAX_OUTPUT_PIXELS
  return {
    rect: g.rect,
    pixelRatio: g.pixelRatio * s,
    width: Math.max(1, Math.floor(g.width * s)),
    height: Math.max(1, Math.floor(g.height * s)),
  };
}

function resolveGeometry(input: ExportGeometryInput): ExportGeometry {
  const { stage, media, crop, naturalWidth, opts } = input;
  if (!good(stage.width) || !good(stage.height)) {
    throw new RangeError("media-editor: cannot export, the canvas has no size");
  }
  const region = opts.region ?? "stage";

  let rect: CropRect;
  if (region === "media") {
    if (!media || !good(media.width) || !good(media.height)) {
      throw new RangeError(
        "media-editor: cannot export region 'media', no photo is shown",
      );
    }
    rect = crop ? intersect(media, crop) : { ...media };
  } else {
    rect = crop
      ? { ...crop }
      : { x: 0, y: 0, width: stage.width, height: stage.height };
  }
  if (!good(rect.width) || !good(rect.height)) {
    throw new RangeError(
      "media-editor: cannot export, the export region is empty",
    );
  }

  const wantW = good(opts.width) ? opts.width : undefined;
  const wantH = good(opts.height) ? opts.height : undefined;

  if (wantW !== undefined && wantH !== undefined) {
    const target = wantW / wantH;
    const have = rect.width / rect.height;
    if (have > target) {
      const w = rect.height * target;
      rect = {
        x: rect.x + (rect.width - w) / 2,
        y: rect.y,
        width: w,
        height: rect.height,
      };
    } else if (have < target) {
      const h = rect.width / target;
      rect = {
        x: rect.x,
        y: rect.y + (rect.height - h) / 2,
        width: rect.width,
        height: h,
      };
    }
    const width = toPx(wantW);
    return { rect, pixelRatio: width / rect.width, width, height: toPx(wantH) };
  }
  if (wantW !== undefined) {
    const width = toPx(wantW);
    return {
      rect,
      pixelRatio: width / rect.width,
      width,
      height: toPx((width * rect.height) / rect.width),
    };
  }
  if (wantH !== undefined) {
    const height = toPx(wantH);
    return {
      rect,
      pixelRatio: height / rect.height,
      width: toPx((height * rect.width) / rect.height),
      height,
    };
  }

  let pixelRatio: number;
  if (good(opts.pixelRatio)) {
    pixelRatio = opts.pixelRatio;
  } else if (region === "media" && media && good(naturalWidth)) {
    pixelRatio = naturalWidth / media.width;
    // The photo's own resolution, but never beyond NATURAL_MAX_EDGE.
    const longest = Math.max(rect.width, rect.height) * pixelRatio;
    if (longest > NATURAL_MAX_EDGE) pixelRatio *= NATURAL_MAX_EDGE / longest;
  } else {
    pixelRatio = DEFAULT_PIXEL_RATIO;
  }

  let width = toPx(rect.width * pixelRatio);
  let height = toPx(rect.height * pixelRatio);
  if (good(opts.maxEdge)) {
    const longest = Math.max(width, height);
    if (longest > opts.maxEdge) {
      const scale = opts.maxEdge / longest;
      pixelRatio *= scale;
      width = toPx(width * scale);
      height = toPx(height * scale);
    }
  }
  return { rect, pixelRatio, width, height };
}

import type {
  CropRect,
  DrawingStroke,
  PlacedSticker,
  StateFrame,
  TextOverlay,
} from "../types";

/** The coordinate-bearing part of the editor state. */
export interface FrameMappable {
  textOverlays: TextOverlay[];
  stickers: PlacedSticker[];
  drawingStrokes: DrawingStroke[];
  crop: CropRect | null;
}

/** x' = ax + x * kx; y' = ay + y * ky; sizes (font, scale, brush) * ks. */
interface Transform {
  ax: number;
  ay: number;
  kx: number;
  ky: number;
  ks: number;
}

const pos = (n: number | undefined): n is number =>
  typeof n === "number" && Number.isFinite(n) && n > 0;

function isIdentity(t: Transform): boolean {
  return t.ax === 0 && t.ay === 0 && t.kx === 1 && t.ky === 1 && t.ks === 1;
}

function frameTransform(from: StateFrame, to: StateFrame): Transform | null {
  if (
    !pos(from.stageWidth) ||
    !pos(from.stageHeight) ||
    !pos(to.stageWidth) ||
    !pos(to.stageHeight)
  ) {
    return null;
  }
  const fm = from.media;
  const tm = to.media;
  if (fm && tm) {
    if (!pos(fm.width) || !pos(tm.width)) return null;
    const k = tm.width / fm.width;
    return {
      ax: tm.x - fm.x * k,
      ay: tm.y - fm.y * k,
      kx: k,
      ky: k,
      ks: k,
    };
  }
  const sx = to.stageWidth / from.stageWidth;
  const sy = to.stageHeight / from.stageHeight;
  return { ax: 0, ay: 0, kx: sx, ky: sy, ks: Math.min(sx, sy) };
}

function apply<T extends FrameMappable>(
  state: T,
  t: Transform,
  crop: CropRect | null,
): T {
  return {
    ...state,
    textOverlays: state.textOverlays.map((o) => ({
      ...o,
      x: t.ax + o.x * t.kx,
      y: t.ay + o.y * t.ky,
      fontSize: o.fontSize * t.ks,
    })),
    stickers: state.stickers.map((s) => ({
      ...s,
      x: t.ax + s.x * t.kx,
      y: t.ay + s.y * t.ky,
      scale: s.scale * t.ks,
    })),
    drawingStrokes: state.drawingStrokes.map((s) => ({
      ...s,
      points: s.points.map((v, i) =>
        i % 2 === 0 ? t.ax + v * t.kx : t.ay + v * t.ky,
      ),
      brushSize: s.brushSize * t.ks,
    })),
    crop,
  };
}

function mapRect(r: CropRect, t: Transform): CropRect {
  return {
    x: t.ax + r.x * t.kx,
    y: t.ay + r.y * t.ky,
    width: r.width * t.kx,
    height: r.height * t.ky,
  };
}

/**
 * Map coordinates recorded in `from` onto `to`. When both frames carry a
 * `media` rect the mapping is uniform (k = to.media.width / from.media.width,
 * origin at the media rect); otherwise x scales by the stage-width ratio, y by
 * the stage-height ratio, and sizes by the smaller of the two. Positions,
 * stroke points and the crop rect move; `fontSize`, sticker `scale` and stroke
 * `brushSize` scale by the size factor. Returns `state` itself (same
 * reference) when the frames are equal or either is degenerate (0 size).
 */
export function mapToFrame<T extends FrameMappable>(
  state: T,
  from: StateFrame,
  to: StateFrame,
): T {
  const t = frameTransform(from, to);
  if (!t || isIdentity(t)) return state;
  return apply(state, t, state.crop ? mapRect(state.crop, t) : null);
}

/**
 * Remap for a crop Apply: the content inside `cropInMedia` (stage px, already
 * intersected with the photo's displayed rect) is shown afterwards at
 * `newMedia` (the cropped photo's displayed rect). Same scaling rules as
 * `mapToFrame`; the returned `crop` is `null`.
 */
export function remapForCrop<T extends FrameMappable>(
  state: T,
  cropInMedia: CropRect,
  newMedia: CropRect,
): T {
  if (!pos(cropInMedia.width) || !pos(newMedia.width)) {
    return state.crop === null ? state : { ...state, crop: null };
  }
  const k = newMedia.width / cropInMedia.width;
  const t: Transform = {
    ax: newMedia.x - cropInMedia.x * k,
    ay: newMedia.y - cropInMedia.y * k,
    kx: k,
    ky: k,
    ks: k,
  };
  if (isIdentity(t)) {
    return state.crop === null ? state : { ...state, crop: null };
  }
  return apply(state, t, null);
}

import type { FontOption, GradientPreset, TextOnlyState } from "../types";

export interface TextCardExportOptions {
  textOnly: TextOnlyState;
  /** Resolved background preset for `textOnly.gradientId` (null: the default). */
  background: GradientPreset | null;
  /** Font list used to resolve `textOnly.fontFamily` to a CSS family. */
  fonts: FontOption[];
  /** Card size in CSS px (the on-screen text surface). */
  width: number;
  height: number;
  /** Output px per CSS px. Default 2. */
  pixelRatio?: number;
  /** Default "image/png". */
  mimeType?: "image/jpeg" | "image/png" | "image/webp";
  /** 0..1, jpeg / webp only. Default 0.9. */
  quality?: number;
  /**
   * The live on-screen font size in CSS px. When given it replaces the
   * 7 %-of-card-width estimate, so the export matches the preview.
   */
  fontSizePx?: number;
  /**
   * The live text box width in CSS px (what the on-screen textarea wraps at).
   * Replaces the fixed 320 px wrap width.
   */
  textBoxWidth?: number;
  /** Text direction of the on-screen surface; sets `ctx.direction`. */
  direction?: "ltr" | "rtl";
}

// Layout constants mirror `parts/text-only-canvas.tsx`:
//   container `px-8` (32px each side), textarea `w-full max-w-[20rem]`,
//   `rows={3}`, font-size clamp(1.5rem, 7vw, 3rem), line-height 1.2,
//   font-weight 600, text-shadow 0 2px 8px rgba(0,0,0,0.25), centred text.
const PAD_X = 32;
const MAX_TEXT_WIDTH = 320;
const MIN_FONT = 24;
const MAX_FONT = 48;
const LINE_HEIGHT = 1.2;
const ROWS = 3;
const FONT_WEIGHT = 600;

// ─── CSS resolution helpers ───────────────────────────────────────────

/**
 * Resolve a CSS value through a temporary element's computed style, so
 * `var(--x)`, `oklch(...)` and friends reach canvas as concrete values.
 */
function resolveViaStyle(
  prop: "color" | "backgroundColor" | "fontFamily",
  value: string,
): string {
  if (typeof document === "undefined" || !document.body) return value;
  const el = document.createElement("span");
  el.style.position = "absolute";
  el.style.visibility = "hidden";
  el.style.pointerEvents = "none";
  el.style[prop] = value;
  document.body.appendChild(el);
  try {
    const computed = window.getComputedStyle(el)[prop];
    return computed && computed.length > 0 ? computed : value;
  } finally {
    el.remove();
  }
}

const TRANSPARENT = /^(transparent|rgba?\(\s*0\s*,\s*0\s*,\s*0\s*,\s*0\s*\)|rgb\(\s*0\s+0\s+0\s*\/\s*0\s*\))$/i;
const COLOR_TOKEN =
  /#[0-9a-f]{3,8}\b|(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch|color)\([^)]*\)/i;

function isTransparent(color: string): boolean {
  return TRANSPARENT.test(color.trim());
}

function resolveColor(value: string): string {
  return resolveViaStyle("color", value);
}

/** Split `a, b(c, d), e` on top-level commas. */
function splitTopLevel(input: string): string[] {
  const out: string[] = [];
  let depth = 0;
  let current = "";
  for (const ch of input) {
    if (ch === "(") depth++;
    if (ch === ")") depth--;
    if (ch === "," && depth === 0) {
      out.push(current.trim());
      current = "";
    } else {
      current += ch;
    }
  }
  if (current.trim()) out.push(current.trim());
  return out;
}

// ─── Gradient parsing ────────────────────────────────────────────────

interface ParsedStop {
  color: string;
  /** Raw position as written (`"40%"`, `"12px"`) or null. */
  position: string | null;
}

interface ParsedGradient {
  /** CSS angle in degrees, or a corner (sx, sy: -1 / +1 in screen axes). */
  direction: { angle: number } | { corner: { sx: number; sy: number } };
  stops: ParsedStop[];
}

const SIDE_ANGLE: Record<string, number> = {
  top: 0,
  right: 90,
  bottom: 180,
  left: 270,
};

function parseDirection(arg: string): ParsedGradient["direction"] | null {
  const angle = /^(-?\d*\.?\d+)(deg|grad|rad|turn)$/i.exec(arg);
  if (angle) {
    const n = Number(angle[1]);
    const unit = angle[2].toLowerCase();
    const deg =
      unit === "deg"
        ? n
        : unit === "grad"
          ? n * 0.9
          : unit === "rad"
            ? (n * 180) / Math.PI
            : n * 360;
    return { angle: deg };
  }
  const to = /^to\s+(.+)$/i.exec(arg);
  if (!to) return null;
  const words = to[1].toLowerCase().split(/\s+/);
  if (words.length === 1 && words[0] in SIDE_ANGLE) {
    return { angle: SIDE_ANGLE[words[0]] };
  }
  if (words.length === 2) {
    const sx = words.includes("right") ? 1 : words.includes("left") ? -1 : 0;
    const sy = words.includes("bottom") ? 1 : words.includes("top") ? -1 : 0;
    if (sx !== 0 && sy !== 0) return { corner: { sx, sy } };
  }
  return null;
}

function parseStop(arg: string): ParsedStop {
  const m = /^(.*\S)\s+(-?\d*\.?\d+(?:%|px))$/.exec(arg);
  if (m) return { color: m[1], position: m[2] };
  return { color: arg, position: null };
}

/** Parse `linear-gradient(...)`; null when the value is anything else. */
function parseLinearGradient(css: string): ParsedGradient | null {
  const m = /^\s*(?:repeating-)?linear-gradient\(([\s\S]*)\)\s*$/i.exec(css);
  if (!m) return null;
  const args = splitTopLevel(m[1]);
  if (args.length < 2) return null;
  let direction: ParsedGradient["direction"] = { angle: 180 };
  let stopArgs = args;
  const dir = parseDirection(args[0]);
  if (dir) {
    direction = dir;
    stopArgs = args.slice(1);
  }
  if (stopArgs.length < 1) return null;
  const stops = stopArgs.map(parseStop);
  return { direction, stops };
}

/** Fill positions: explicit ones (as fractions), the rest spread evenly. */
function stopOffsets(stops: ParsedStop[], lineLength: number): number[] {
  const offsets: Array<number | null> = stops.map((s) => {
    if (!s.position) return null;
    const n = parseFloat(s.position);
    if (s.position.endsWith("%")) return n / 100;
    return lineLength > 0 ? n / lineLength : 0;
  });
  if (offsets[0] === null) offsets[0] = 0;
  const last = offsets.length - 1;
  if (offsets[last] === null) offsets[last] = 1;
  let prev = 0;
  for (let i = 1; i <= last; i++) {
    if (offsets[i] === null) {
      let next = i;
      while (offsets[next] === null) next++;
      const a = offsets[prev] as number;
      const b = offsets[next] as number;
      for (let j = prev + 1; j < next; j++) {
        offsets[j] = a + ((b - a) * (j - prev)) / (next - prev);
      }
      i = next;
    }
    prev = i;
  }
  let running = -Infinity;
  return offsets.map((o) => {
    running = Math.max(running, o as number);
    return Math.min(1, Math.max(0, running));
  });
}

function buildGradient(
  ctx: CanvasRenderingContext2D,
  g: ParsedGradient,
  w: number,
  h: number,
): CanvasGradient {
  let dx: number;
  let dy: number;
  if ("angle" in g.direction) {
    const rad = (g.direction.angle * Math.PI) / 180;
    dx = Math.sin(rad);
    dy = -Math.cos(rad);
  } else {
    const { sx, sy } = g.direction.corner;
    const nx = sx * h;
    const ny = sy * w;
    const len = Math.hypot(nx, ny) || 1;
    dx = nx / len;
    dy = ny / len;
  }
  const length = Math.abs(w * dx) + Math.abs(h * dy);
  const cx = w / 2;
  const cy = h / 2;
  const gradient = ctx.createLinearGradient(
    cx - (dx * length) / 2,
    cy - (dy * length) / 2,
    cx + (dx * length) / 2,
    cy + (dy * length) / 2,
  );
  const offsets = stopOffsets(g.stops, length);
  g.stops.forEach((s, i) => {
    gradient.addColorStop(offsets[i], resolveColor(s.color));
  });
  return gradient;
}

/** A fill style for any `GradientPreset.background` value. */
function backgroundFill(
  ctx: CanvasRenderingContext2D,
  css: string,
  w: number,
  h: number,
): string | CanvasGradient {
  const parsed = parseLinearGradient(css);
  if (parsed) return buildGradient(ctx, parsed, w, h);
  // Plain colour, or anything else (radial / conic / layered / var(...)).
  const resolved = resolveViaStyle("backgroundColor", css);
  if (
    resolved.trim() !== "" &&
    !isTransparent(resolved) &&
    !/gradient\(|url\(|var\(/i.test(resolved)
  ) {
    return resolved;
  }
  const token = COLOR_TOKEN.exec(css);
  if (token) return resolveColor(token[0]);
  return "black";
}

// ─── Text layout ─────────────────────────────────────────────────────

/** Wrap one paragraph to `maxWidth`, breaking over-long words by character. */
function wrapParagraph(
  ctx: CanvasRenderingContext2D,
  paragraph: string,
  maxWidth: number,
): string[] {
  if (paragraph === "") return [""];
  const lines: string[] = [];
  let line = "";
  const fits = (s: string) => ctx.measureText(s).width <= maxWidth;
  for (const word of (paragraph.match(/\S+\s*|\s+/g) ?? [])) {
    const candidate = line + word;
    if (fits(candidate.trimEnd())) {
      line = candidate;
      continue;
    }
    if (line !== "") {
      lines.push(line.trimEnd());
      line = "";
    }
    if (fits(word.trimEnd())) {
      line = word;
      continue;
    }
    for (const ch of word) {
      if (line !== "" && !fits(line + ch)) {
        lines.push(line);
        line = "";
      }
      line += ch;
    }
  }
  lines.push(line.trimEnd());
  return lines;
}

function resolveFamily(textOnly: TextOnlyState, fonts: FontOption[]): string {
  const match = fonts.find(
    (f) => f.family === textOnly.fontFamily || f.id === textOnly.fontFamily,
  );
  const family = match ? match.family : textOnly.fontFamily;
  if (!family) return "sans-serif";
  return resolveViaStyle("fontFamily", family);
}

/**
 * Draw a text card with Canvas 2D (no DOM clone, no SVG foreignObject): the
 * background (solid colour or CSS linear-gradient parsed into a canvas
 * gradient) and the wrapped, centred text laid out like `TextOnlyCanvas`.
 * Waits for the font (`document.fonts.load`) before drawing.
 *
 * Layout note: the on-screen textarea is `rows={3}` and scrolls beyond that;
 * an export must not lose text, so more than three lines are laid out as one
 * block centred on the card instead.
 */
export async function exportTextCardBlob(
  opts: TextCardExportOptions,
): Promise<{ blob: Blob; width: number; height: number }> {
  const {
    textOnly,
    background,
    fonts,
    width,
    height,
    pixelRatio = 2,
    mimeType = "image/png",
    quality = 0.9,
    fontSizePx,
    textBoxWidth,
    direction,
  } = opts;

  const family = resolveFamily(textOnly, fonts);
  // The live size wins; else the on-screen `7vw` is estimated from the card's
  // own width (the closest stand-in).
  const fontSize =
    typeof fontSizePx === "number" && Number.isFinite(fontSizePx) && fontSizePx > 0
      ? fontSizePx
      : Math.round(Math.min(MAX_FONT, Math.max(MIN_FONT, width * 0.07)) * 100) / 100;
  const font = `${FONT_WEIGHT} ${fontSize}px ${family}`;

  try {
    await document.fonts?.load(font, textOnly.text || undefined);
  } catch {
    // An unavailable font falls back to the next family in the stack.
  }

  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(width * pixelRatio));
  canvas.height = Math.max(1, Math.round(height * pixelRatio));
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("media-editor: 2D canvas context unavailable");
  ctx.scale(pixelRatio, pixelRatio);

  // Background (the on-screen surface falls back to black).
  ctx.fillStyle = backgroundFill(ctx, background?.background ?? "black", width, height);
  ctx.fillRect(0, 0, width, height);

  // Text.
  ctx.font = font;
  if (direction) ctx.direction = direction;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = resolveColor(textOnly.textColor);
  ctx.shadowColor = "rgba(0, 0, 0, 0.25)";
  ctx.shadowBlur = 8 * pixelRatio;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 2 * pixelRatio;

  const boxWidth =
    typeof textBoxWidth === "number" && Number.isFinite(textBoxWidth) && textBoxWidth > 0
      ? Math.max(1, Math.min(textBoxWidth, width))
      : Math.max(1, Math.min(MAX_TEXT_WIDTH, width - PAD_X * 2));
  const lineHeight = fontSize * LINE_HEIGHT;
  const lines = textOnly.text
    .split("\n")
    .flatMap((p) => wrapParagraph(ctx, p, boxWidth));
  const blockLines = Math.max(lines.length, ROWS);
  const top = (height - blockLines * lineHeight) / 2;
  // Fewer than 3 lines sit at the top of the 3-row textarea; more are centred.
  lines.forEach((line, i) => {
    if (line === "") return;
    ctx.fillText(line, width / 2, top + (i + 0.5) * lineHeight);
  });

  const blob = await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob(
      (b) =>
        b ? resolve(b) : reject(new Error("media-editor: canvas.toBlob returned null")),
      mimeType,
      mimeType === "image/png" ? undefined : quality,
    );
  });
  return { blob, width: canvas.width, height: canvas.height };
}
